RETURNS void
LANGUAGE plpgsql
AS $$
DECLARE
    v_actor_rank integer;
    v_required_rank integer;
BEGIN
    SELECT arr.role_rank
    INTO v_actor_rank
    FROM workflow.actor_role_rank arr
    WHERE arr.role_code = p_actor_role;

    IF v_actor_rank IS NULL THEN
        RAISE EXCEPTION
            USING
