            FROM workflow.case_followup_work cfw
            WHERE cfw.status = 'pending'
              AND cfw.due_at <= clock_timestamp()
            ORDER BY cfw.due_at, cfw.created_at
            LIMIT p_batch_size
            FOR UPDATE SKIP LOCKED
