            locked_by = p_worker_name,
            locked_until = clock_timestamp() + interval '5 minutes',
            attempt_count = cfw.attempt_count + 1
        FROM due
        WHERE cfw.work_id = due.work_id
        RETURNING cfw.*
    LOOP
